// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address embeddedOwner) public {
        // Admissible domain: the embedded owner must be a real (nonzero) address
        vm.assume(embeddedOwner != address(0));

        // Build an owner() call whose calldata mimics a clone invocation:
        // 4-byte selector + one 32-byte word + 2-byte little-endian length (34).
        // Immutable-args offset = 38 - (34 + 2) = 2.
        // owner() = shr(0x60, calldataload(2)) -> bytes 10..29 of the appended word.
        bytes memory arg = new bytes(32);
        // place embeddedOwner at bytes 10..29 of the word
        for (uint256 i = 0; i < 20; i++) {
            arg[10 + i] = bytes20(embeddedOwner)[i];
        }
        bytes memory data = abi.encodePacked(C.owner.selector, arg, uint16(34));

        (bool ok, bytes memory ret) = address(c).call(data);
        assertTrue(ok && ret.length == 32 && abi.decode(ret, (address)) == embeddedOwner);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address a) public {
        // Admissible domain: owner() reads the immutable arg at calldata offset
        // (calldatasize - 2 - low16(a)) = (36 - 2 - 0x22) = 0, so the arg read
        // by the reference is exactly the top 20 bytes of the calldata word == a.
        // Keep a nonzero so the mutant's out-of-bounds read (returns 0) is caught.
        vm.assume(a != address(0));
        vm.assume(uint160(a) & 0xffff == 0x22);

        // Drive c through `owner`: send calldata selector ++ a (owner takes no
        // declared args, but reads its raw calldata for immutable args).
        (bool ok, bytes memory ret) = address(c).call(
            abi.encodeWithSelector(c.owner.selector, a)
        );

        // General rule: the reported owner equals the address word embedded at
        // immutable-arg offset 0x0 (here: a). The mutant reads offset 0x3c,
        // past the end of calldata, yielding address(0) != a.
        assertTrue(ok && abi.decode(ret, (address)) == a);
    }
}

