pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C, CoolerFactory} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    CoolerFactory factory;

    function setUp() public {
        c = new C();
        factory = new CoolerFactory();
    }

    function testFuzz_property(uint160 seedActor, uint160 seedColl) public {
        address actor = address(seedActor);
        address coll = address(seedColl);
        vm.assume(actor != address(0));
        vm.assume(coll != address(0));
        vm.assume(actor != coll);

        vm.prank(actor);
        address cooler = factory.generateCooler(
            CoolerFactory(coll).collateral.erc20(),
            CoolerFactory(coll).collateral.erc20()
        );
        assertTrue(C(cooler).collateral() != C(cooler).owner());
    }
}

