// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C, CoolerFactory, ERC20} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    CoolerFactory factory;

    function setUp() public {
        c = new C();
        factory = new CoolerFactory();
    }

    function testFuzz_property(address collateralToken, address debtToken) public {
        // Keep the domain wide: any two distinct non-zero addresses are admissible.
        vm.assume(collateralToken != address(0));
        vm.assume(debtToken != address(0));
        vm.assume(collateralToken != debtToken);

        // The factory deploys a clone of C with immutable args packed as:
        // owner @0x00, collateral @0x14, debt @0x28, factory @0x3c.
        address cooler = factory.generateCooler(ERC20(collateralToken), ERC20(debtToken));
        vm.assume(cooler != address(0));

        // General rule: collateral() must always report the token stored at
        // immutable-arg offset 0x14 (the collateral token). The mutant reads
        // offset 0x28 and returns the debt token instead, violating this
        // for every input where collateralToken != debtToken.
        assertTrue(C(cooler).collateral() == ERC20(collateralToken));
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // General rule: with immutable-args layout [collateralToken at offset 0x14,
    // debtToken at offset 0x28], c.collateral() must ALWAYS return the token
    // stored at offset 0x14. The buggy collateral() reads 0x28 and returns the
    // debt token instead, which differs whenever the two tokens differ.
    // We drive the pure getter via a raw call whose appended tail acts as the
    // immutable-args region (selector + 72 bytes of args + 2-byte length),
    // exactly as a factory clone's calldata would look.
    function testFuzz_property(address tokenA, address tokenB) public {
        vm.assume(tokenA != address(0));
        vm.assume(tokenB != address(0));
        vm.assume(tokenA != tokenB);

        // 72-byte args region: 32 zero bytes, then tokenA at byte 32 (== calldata
        // offset 0x24, the 20 bytes read by _getArgAddress(0x14)), then tokenB at
        // byte 52 (== 20 bytes read by _getArgAddress(0x28)).
        bytes memory data = abi.encodePacked(bytes32(0), tokenA, tokenB);
        bytes memory payload = abi.encodePacked(
            C.collateral.selector,
            data,
            bytes2(uint16(data.length)) // trailing 2-byte length, as in clones
        );

        (bool ok, bytes memory ret) = address(c).call(payload);
        assertTrue(ok && ret.length == 32 && abi.decode(ret, (address)) == tokenA);
    }
}

