pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C, CoolerFactory} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    CoolerFactory f;
    function setUp() public { f = new CoolerFactory(); }

    function testFuzz_property(address coll, address debtTok, address actor) public {
        vm.assume(actor != address(0));
        vm.assume(coll != address(f));
        vm.assume(debtTok != address(f));

        vm.prank(actor);
        address cooler = f.generateCooler(coll == address(0) ? address(uint160(1)) : ERC20(coll), debtTok == address(0) ? ERC20(address(uint160(2))) : ERC20(debtTok));

        C c = C(cooler);
        ERC20 reportedCollateral = c.collateral();
        CoolerFactory reportedFactory = c.factory();
        assertTrue(address(reportedCollateral) != address(reportedFactory));
    }
}
